package io.github.ningpp.compat;

import java.lang.foreign.MemorySegment;
import java.lang.foreign.ValueLayout;

/**
 * Replacement for System.Text.Encodings.Web.JavaScriptEncoder (generated by
 * CSharpToJava converter). Scalar implementation: JSON special characters
 * (control chars, quotes, backslash) are escaped; non-ASCII characters are
 * escaped by the default encoder and preserved by UnsafeRelaxedJsonEscaping.
 */
public class JavaScriptEncoder {
    private final boolean escapeNonAscii;
    private final UnicodeRange[] allowedRanges;

    private static final JavaScriptEncoder DEFAULT = new JavaScriptEncoder(true, null);
    private static final JavaScriptEncoder UNSAFE_RELAXED = new JavaScriptEncoder(false, UnicodeRanges.getUnsafeRelaxedRanges());

    private JavaScriptEncoder(boolean escapeNonAscii, UnicodeRange[] allowedRanges) {
        this.escapeNonAscii = escapeNonAscii;
        this.allowedRanges = allowedRanges;
    }

    /** Mirrors JavaScriptEncoder.Default. */
    public static JavaScriptEncoder getDefault() {
        return DEFAULT;
    }

    /** Mirrors JavaScriptEncoder.UnsafeRelaxedJsonEscaping. */
    public static JavaScriptEncoder getUnsafeRelaxedJsonEscaping() {
        return UNSAFE_RELAXED;
    }

    /** Mirrors JavaScriptEncoder.Create(UnicodeRange... allowedRanges). */
    public static JavaScriptEncoder create(UnicodeRange... allowedRanges) {
        return new JavaScriptEncoder(true, allowedRanges);
    }

    /** Mirrors JavaScriptEncoder.Create(TextEncoderSettings settings). */
    public static JavaScriptEncoder create(TextEncoderSettings settings) {
        if (settings == null) {
            throw new NullPointerException("settings");
        }
        return new JavaScriptEncoder(true, null);
    }

    /** Protected no-arg constructor for test subclasses (e.g. CustomEncoderAllowingPlusSign). */
    protected JavaScriptEncoder() {
        this(true, null);
    }

    /** C# JavaScriptEncoder.WillEncode(int) — whether the given Unicode scalar requires escaping. */
    public boolean willEncode(int unicodeScalar) {
        if (unicodeScalar < 0x20 || unicodeScalar == '"' || unicodeScalar == '\\') {
            return true;
        }
        if (unicodeScalar < 0x7F) {
            // HTML-sensitive ASCII characters are always escaped by the default
            // and Create(...) encoders; UnsafeRelaxedJsonEscaping allows them.
            if (escapeNonAscii && isHtmlSensitiveAscii(unicodeScalar)) {
                return true;
            }
            if (allowedRanges != null) {
                // Create(allowedRanges) allows ONLY the listed ranges, so ASCII
                // outside them is escaped too (e.g. Create(0x80..0xFF) escapes
                // 'a' as \u0061).
                return !isInAllowedRanges(unicodeScalar);
            }
            return false;
        }
        // .NET's global block list always escapes supplementary (non-BMP)
        // characters, regardless of the encoder's allowed ranges — no built-in
        // encoder writes surrogate pairs unescaped.
        if (unicodeScalar >= 0x10000) {
            return true;
        }
        if (allowedRanges != null && isInAllowedRanges(unicodeScalar)) {
            return false;
        }
        if (escapeNonAscii) {
            return true;
        }
        return false;
    }

    private boolean isInAllowedRanges(int unicodeScalar) {
        if (allowedRanges != null) {
            for (UnicodeRange range : allowedRanges) {
                if (range != null && range.contains(unicodeScalar)) {
                    return true;
                }
            }
        }
        return false;
    }

    private static boolean isHtmlSensitiveAscii(int ch) {
        return ch == '<' || ch == '>' || ch == '&' || ch == '\'' || ch == '+' || ch == '`';
    }

    /** C# JavaScriptEncoder.MaxOutputCharactersPerInputCharacter. */
    public int getMaxOutputCharactersPerInputCharacter() {
        return 6;
    }

    /**
     * C# JavaScriptEncoder.TryEncodeUnicodeScalar(int, Span&lt;byte&gt;, out int) —
     * writes the escaped UTF-16 text into the buffer segment.
     */
    public boolean tryEncodeUnicodeScalar(int unicodeScalar, MemorySegment buffer, int bufferLength,
                                          IntHolder numberOfCharactersWritten) {
        String text;
        if (willEncode(unicodeScalar)) {
            if (unicodeScalar > 0xFFFF) {
                // .NET escapes supplementary scalars as two surrogate escapes.
                char[] pair = Character.toChars(unicodeScalar);
                text = "\\u" + String.format("%04X", (int) pair[0])
                    + "\\u" + String.format("%04X", (int) pair[1]);
            } else {
                text = "\\u" + String.format("%04X", unicodeScalar);
            }
        } else {
            text = String.valueOf(Character.toChars(unicodeScalar));
        }
        if (bufferLength < text.length()) {
            return false;
        }
        for (int i = 0; i < text.length(); i++) {
            buffer.set(ValueLayout.JAVA_CHAR, (long) i * 2, text.charAt(i));
        }
        numberOfCharactersWritten.value = text.length();
        return true;
    }

    /**
     * Mirrors JavaScriptEncoder.FindFirstCharacterToEncodeUtf8(ReadOnlySpan&lt;byte&gt;).
     * Returns the index of the first byte that requires escaping, or -1.
     */
    public int findFirstCharacterToEncodeUtf8(ReadOnlySpan<Integer> utf8Text) {
        int i = 0;
        while (i < utf8Text.length()) {
            int b = utf8Text.get(i) & 0xFF;
            if (b < 0x80) {
                // Virtual WillEncode so derived encoders can allow ASCII.
                if (willEncode(b)) {
                    return i;
                }
                i++;
            } else {
                int[] decoded = decodeUtf8Scalar(utf8Text, i);
                if (willEncode(decoded[0])) {
                    return i;
                }
                i += decoded[1];
            }
        }
        return -1;
    }

    /**
     * Mirrors JavaScriptEncoder.FindFirstCharacterToEncode(char*, int) — scans the
     * UTF-16 characters in a memory segment.
     */
    public int findFirstCharacterToEncode(MemorySegment ptr, int length) {
        for (int i = 0; i < length; i++) {
            int ch = ptr.get(ValueLayout.JAVA_CHAR, (long) i * 2);
            if (needsEscapingUtf16(ch)) {
                return i;
            }
        }
        return -1;
    }

    /**
     * Mirrors JavaScriptEncoder.EncodeUtf8(ReadOnlySpan&lt;byte&gt;, Span&lt;byte&gt;, out int, out int).
     * Escapes control characters, quote and backslash as Unicode escape sequences (backslash-u-XXXX).
     */
    public OperationStatus encodeUtf8(ReadOnlySpan<Integer> source, Span<Integer> destination,
                                      IntHolder bytesConsumed, IntHolder bytesWritten) {
        int written = 0;
        int consumed = 0;
        while (consumed < source.length()) {
            int b = source.get(consumed) & 0xFF;
            if (b < 0x80) {
                // C# calls the (virtual) WillEncode for every character, so a
                // derived encoder can allow ASCII characters (e.g. '+') that the
                // base HTML-sensitive rules would escape.
                if (!willEncode(b)) {
                    if (written >= destination.length()) {
                        return OperationStatus.DestinationTooSmall;
                    }
                    destination.set(written++, b);
                    consumed++;
                    continue;
                }
                String escaped = asciiEscape(b);
                if (written + escaped.length() > destination.length()) {
                    return OperationStatus.DestinationTooSmall;
                }
                byte[] escBytes = escaped.getBytes(java.nio.charset.StandardCharsets.US_ASCII);
                for (byte e : escBytes) {
                    destination.set(written++, e & 0xFF);
                }
                consumed++;
                continue;
            }
            // Non-ASCII: decode the full UTF-8 scalar before deciding to escape.
            int[] decoded = decodeUtf8Scalar(source, consumed);
            int scalar = decoded[0];
            int byteLen = decoded[1];
            if (willEncode(scalar)) {
                String escaped;
                if (scalar <= 0xFFFF) {
                    escaped = "\\u" + String.format("%04X", scalar);
                } else {
                    char[] pair = Character.toChars(scalar);
                    escaped = "\\u" + String.format("%04X", (int) pair[0])
                        + "\\u" + String.format("%04X", (int) pair[1]);
                }
                if (written + escaped.length() > destination.length()) {
                    return OperationStatus.DestinationTooSmall;
                }
                byte[] escBytes = escaped.getBytes(java.nio.charset.StandardCharsets.US_ASCII);
                for (byte e : escBytes) {
                    destination.set(written++, e & 0xFF);
                }
            } else {
                if (written + byteLen > destination.length()) {
                    return OperationStatus.DestinationTooSmall;
                }
                for (int k = 0; k < byteLen; k++) {
                    destination.set(written++, source.get(consumed + k) & 0xFF);
                }
            }
            consumed += byteLen;
        }
        bytesConsumed.value = consumed;
        bytesWritten.value = written;
        return OperationStatus.Done;
    }

    private String asciiEscape(int b) {
        if (b == '"' && !escapeNonAscii) {
            // UnsafeRelaxedJsonEscaping escapes the quote with the short \" form;
            // the default encoder uses \u0022.
            return "\\\"";
        }
        return switch (b) {
            case 0x08 -> "\\b";
            case 0x09 -> "\\t";
            case 0x0A -> "\\n";
            case 0x0C -> "\\f";
            case 0x0D -> "\\r";
            case 0x5C -> "\\\\";
            default -> "\\u" + String.format("%04X", b);
        };
    }

    /** Decodes one UTF-8 scalar starting at index; returns {codePoint, byteLength} (invalid input -> {0xFFFD, consumedBytes}). */
    private static int[] decodeUtf8Scalar(ReadOnlySpan<Integer> source, int index) {
        int b0 = source.get(index) & 0xFF;
        int length;
        if ((b0 & 0xE0) == 0xC0) {
            length = 2;
        } else if ((b0 & 0xF0) == 0xE0) {
            length = 3;
        } else if ((b0 & 0xF8) == 0xF0) {
            length = 4;
        } else {
            return new int[] { 0xFFFD, 1 };
        }
        if (index + length > source.length()) {
            // Truncated sequence: .NET replaces the partial prefix with one U+FFFD.
            return new int[] { 0xFFFD, source.length() - index };
        }
        int cp = b0 & (0xFF >> (length + 1));
        int k = 1;
        for (; k < length; k++) {
            int bk = source.get(index + k) & 0xFF;
            if ((bk & 0xC0) != 0x80) {
                // Not a continuation byte: .NET replaces the whole consumed
                // prefix (lead byte + continuation bytes seen) with a single
                // U+FFFD and resumes at the offending byte.
                return new int[] { 0xFFFD, k };
            }
            cp = (cp << 6) | (bk & 0x3F);
        }
        // Reject overlong/surrogate/out-of-range encodings.
        int min = switch (length) {
            case 2 -> 0x80;
            case 3 -> 0x800;
            default -> 0x10000;
        };
        if (cp < min || cp > 0x10FFFF || (cp >= 0xD800 && cp <= 0xDFFF)) {
            return new int[] { 0xFFFD, length };
        }
        return new int[] { cp, length };
    }

    /**
     * Mirrors JavaScriptEncoder.Encode(ReadOnlySpan&lt;char&gt;, Span&lt;byte&gt;, out int, out int).
     * Encodes UTF-16 characters to escaped UTF-8 bytes. The destination is a raw Span
     * so both byte-span and char-span call sites erase to the same Java signature.
     */
    @SuppressWarnings({ "unchecked", "rawtypes" })
    public OperationStatus encode(ReadOnlySpan<Character> source, Span destination,
                                  IntHolder charsConsumed, IntHolder bytesWritten) {
        boolean charBacked = destination.getBackingArray() instanceof char[]
            || destination.getBackingArray() instanceof Character[];
        int written = 0;
        int consumed = 0;
        while (consumed < source.length()) {
            int ch = source.get(consumed);
            int scalar;
            int consumedNext;
            if (Character.isHighSurrogate((char) ch)
                    && consumed + 1 < source.length()
                    && Character.isLowSurrogate((char) (int) source.get(consumed + 1))) {
                // A valid pair is ONE scalar; .NET escapes supplementary scalars as the two
                // backslash-u units of the pair and never as a raw 4-byte sequence.
                scalar = Character.toCodePoint((char) ch, (char) (int) source.get(consumed + 1));
                consumedNext = consumed + 2;
            } else if (Character.isSurrogate((char) ch)) {
                // A LONE surrogate is invalid UTF-16, so .NET's encoder replaces it with U+FFFD —
                // it never emits the surrogate itself. Measured before this fix: writing the
                // property name {0xD801,'a'} produced "\ud801a" where .NET produces "\uFFFDa".
                scalar = 0xFFFD;
                consumedNext = consumed + 1;
            } else {
                scalar = ch;
                consumedNext = consumed + 1;
            }
            if (willEncode(scalar)) {
                String esc = escapeScalarText(scalar, charBacked);
                if (written + esc.length() > destination.length()) {
                    return OperationStatus.DestinationTooSmall;
                }
                for (int k = 0; k < esc.length(); k++) {
                    // Separate branches: a ternary mixing char and int degrades to the
                    // set(int, Object) overload and blows up with ArrayStoreException on a
                    // char-backed destination span.
                    if (charBacked) {
                        destination.set(written++, esc.charAt(k));
                    } else {
                        destination.set(written++, (int) (esc.charAt(k) & 0xFF));
                    }
                }
                consumed = consumedNext;
                continue;
            }
            if (charBacked) {
                if (written + (consumedNext - consumed) > destination.length()) {
                    return OperationStatus.DestinationTooSmall;
                }
                destination.set(written++, (char) ch);
                if (consumedNext - consumed == 2) {
                    destination.set(written++, (char) (int) source.get(consumed + 1));
                }
            } else {
                byte[] utf8 = new String(Character.toChars(scalar))
                    .getBytes(java.nio.charset.StandardCharsets.UTF_8);
                if (written + utf8.length > destination.length()) {
                    return OperationStatus.DestinationTooSmall;
                }
                for (byte e : utf8) {
                    destination.set(written++, e & 0xFF);
                }
            }
            consumed = consumedNext;
        }
        charsConsumed.value = consumed;
        bytesWritten.value = written;
        return OperationStatus.Done;
    }

    /**
     * The escaped text for one Unicode scalar: a short form for ASCII, otherwise a
     * {@code backslash-u} escape — two units for a supplementary scalar, one for everything else.
     */
    private String escapeScalarText(int scalar, boolean charBacked) {
        if (scalar < 0x80) {
            String shortEsc = asciiEscape(scalar);
            if (shortEsc != null) {
                return shortEsc;
            }
        }
        if (scalar > 0xFFFF) {
            char[] pair = Character.toChars(scalar);
            return "\\u" + String.format("%04X", (int) pair[0])
                + "\\u" + String.format("%04X", (int) pair[1]);
        }
        return "\\u" + String.format("%04X", scalar);
    }

    @SuppressWarnings({ "unchecked", "rawtypes" })
    public OperationStatus encode(Span<Character> source, Span destination,
                                  IntHolder charsConsumed, IntHolder bytesWritten) {
        return encode(new ReadOnlySpan<>(source.toArray(), 0, source.getLength()),
            destination, charsConsumed, bytesWritten);
    }

    private boolean needsEscaping(int b) {
        if (b < 0x20 || b == '"' || b == '\\') {
            return true;
        }
        if (b < 0x80) {
            if (escapeNonAscii && isHtmlSensitiveAscii(b)) {
                return true;
            }
            if (allowedRanges != null) {
                // Create(allowedRanges) allows ONLY the listed ranges, so ASCII
                // outside them is escaped too.
                return !isInAllowedRanges(b);
            }
            return false;
        }
        if (allowedRanges != null && isInAllowedRanges(b)) {
            return false;
        }
        return escapeNonAscii;
    }

    private boolean needsEscapingUtf16(int ch) {
        if (ch < 0x20 || ch == '"' || ch == '\\') {
            return true;
        }
        if (ch < 0x80) {
            if (escapeNonAscii) {
                return isHtmlSensitiveAscii(ch);
            }
            return false;
        }
        if (!escapeNonAscii && allowedRanges == null) {
            return false;
        }
        if (allowedRanges != null) {
            for (UnicodeRange range : allowedRanges) {
                if (range != null && range.contains(ch)) {
                    return false;
                }
            }
        }
        return true;
    }
}
